        {"kind": "number", "id": "num-6"}
      ],
      "problem": "The latency element animates a single round-trip value from 0.4 to 2.1 ms with its colour turning to problem, so the board draws the median and the p99 — two points of the same measurement — as a change over time.",
      "fix": "Show 0.4 ms and 2.1 ms as two separately labelled values (median and p99) instead of a counter transition between them."
    },
    {
      "beatId": "beat5",
      "category": "above_level",
      "severity": "advisory",
      "owner": "scriptwriter",
      "fields": ["narration"],
      "evidence": [
        {"kind": "narration", "quote": "At p ninety-nine, two point one."}
      ],
      "problem": "\"p ninety-nine\" is used bare; a beginner who does not know percentiles cannot tell that 2.1 ms is the slow tail of the same trip rather than a new measurement.",
      "fix": "Gloss it in the sentence, e.g. \"the slowest one percent of trips, two point one milliseconds\"."
    },
    {
      "beatId": "beat7",
      "category": "missing_trade_off",
      "severity": "advisory",
      "owner": "director",
      "fields": ["plan"],
      "evidence": [
        {"kind": "note", "quote": "Fail open was chosen for checkout deliberately — refusing payments because the limiter's store is slow loses sales on every request"}
      ],
      "problem": "The beat has the limiter let requests through uncounted as if it were an accident, skipping the trade-off in the notes that fail open was a deliberate choice for checkout before the downstream contract made it wrong.",
      "fix": "Plan one short clause in beat7 giving the reason fail open was configured — refusing payments when the store is slow loses sales — so the incident reads as a trade-off, not an oversight."
    }
  ]
